<?php
declare(strict_types=1);namespace App\Modules\SupplierPayments\Services;use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\SupplierPayments\DTOs\SupplierPaymentData;use App\Modules\SupplierPayments\DTOs\SupplierPaymentTableQuery;use App\Modules\SupplierPayments\Repositories\SupplierPaymentRepository;use App\Shared\Numbering\NumberGeneratorService;final class SupplierPaymentService{public function __construct(private readonly SupplierPaymentRepository$r,private readonly NumberGeneratorService$n,private readonly Database$db,private readonly Auth$auth){}public function find(int$id):array{$p=$this->r->find($id)??throw new BusinessRuleException('دفعة المورد غير موجودة.');if($p['status']==='posted')$p=array_replace($p,$this->r->historicalIdentity($id)??[]);return$p;}public function summary(int$invoiceId):array{$i=$this->invoice($invoiceId);$paid=$this->r->postedTotal($invoiceId);return$this->r->payable((string)$i['total_amount'],$paid);}public function invoice(int$id):array{return$this->r->invoice($id)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');}
public function save(SupplierPaymentData$d,?int$id=null):int{return$this->db->transaction(function()use($d,$id){$i=$this->r->invoice($d->supplierInvoiceId,true)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');if($i['status']!=='approved')throw new BusinessRuleException('يمكن الدفع لفاتورة مورد معتمدة فقط.');$old=$id===null?null:$this->r->findForInvoice($id,$d->supplierInvoiceId,true);if($id!==null&&($old===null||$old['status']!=='draft'))throw new BusinessRuleException('الدفعة غير قابلة للتعديل.');if($old!==null&&preg_match('/^SUPAY-(\d{4})-/',(string)$old['payment_code'],$m)&&$m[1]!==substr($d->paymentDate,0,4))throw new BusinessRuleException('لا يمكن تغيير سنة تاريخ الدفع. ألغِ المسودة وأنشئ دفعة جديدة.');if($id===null)return$this->r->create($this->n->nextSupplierPaymentCode((int)substr($d->paymentDate,0,4)),$d,$i,$this->user());$this->r->update($id,$d);return$id;});}
public function post(int$id):void{$probe=$this->find($id);$this->db->transaction(function()use($id,$probe){$invoiceId=(int)$probe['supplier_invoice_id'];$i=$this->r->invoice($invoiceId,true)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');$p=$this->r->findForInvoice($id,$invoiceId,true)??throw new BusinessRuleException('تغيرت فاتورة الدفعة أثناء العملية. أعد المحاولة.');if($p['status']!=='draft')throw new BusinessRuleException('يمكن ترحيل مسودة الدفعة فقط.');if($i['status']!=='approved')throw new BusinessRuleException('يمكن الدفع لفاتورة مورد معتمدة فقط.');$paid=$this->r->postedTotal($invoiceId);$x=$this->r->payable((string)$i['total_amount'],$paid);if($this->r->exceeds((string)$p['amount'],(string)$x['remaining']))throw new BusinessRuleException('مبلغ الدفعة يتجاوز المتبقي على الفاتورة.');$after=$this->r->payable((string)$x['remaining'],(string)$p['amount']);$this->r->post($id,$this->user(),$i,$paid,(string)$after['remaining']);$v=$this->r->find($id,true);if(($v['status']??null)!=='posted')throw new \RuntimeException('Supplier payment posting failed.');});}public function cancel(int$id):void{$probe=$this->find($id);$this->db->transaction(function()use($id,$probe){$invoiceId=(int)$probe['supplier_invoice_id'];$this->r->invoice($invoiceId,true);$p=$this->r->findForInvoice($id,$invoiceId,true)??throw new BusinessRuleException('تغيرت فاتورة الدفعة أثناء العملية.');if($p['status']!=='draft')throw new BusinessRuleException('يمكن إلغاء مسودة الدفعة فقط.');$this->r->cancel($id,$this->user());});}public function references():array{return$this->r->references();}public function dataTable(SupplierPaymentTableQuery$q):array{$x=$this->r->dataTable($q);$posted=array_values(array_filter($x['rows'],static fn(array$row):bool=>$row['status']==='posted'));$history=$this->r->historicalIdentities(array_map('intval',array_column($posted,'id')));foreach($x['rows']as&$row)if($row['status']==='posted')$row=array_replace($row,$history[$row['id']]??[]);unset($row);return['draw'=>$q->draw,'recordsTotal'=>$x['recordsTotal'],'recordsFiltered'=>$x['recordsFiltered'],'data'=>$x['rows']];}private function user():int{return$this->auth->id()??throw new BusinessRuleException('تعذر تحديد المستخدم الحالي.');}}
